require __DIR__.'/../inc/bootstrap.php';$id=(int)($_GET['id']??$_POST['id']??0);$stmt=$db->prepare('SELECT * FROM forms WHERE id=?');$stmt->execute([$id]);$form=$stmt->fetch();if(!$form){http_response_code(404);exit('Form not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$title=trim((string)($_POST['title']??''));$location=(string)($_POST['location']??'');$description=trim((string)($_POST['description']??''));$active=isset($_POST['is_active'])?1:0;$labels=$_POST['field_label']??[];$types=$_POST['field_type']??[];$keys=$_POST['field_key']??[];$required=$_POST['field_required']??[];$placeholders=$_POST['field_placeholder']??[];$helps=$_POST['field_help']??[];$options=$_POST['field_options']??[];$condFields=$_POST['condition_field']??[];$condOps=$_POST['condition_operator']??[];$condValues=$_POST['condition_value']??[];
 if(!$title||!isset(locations()[$location])){flash('error','Enter a title and valid location.');redirect('gadmin8f3k2p9x7m4q6v1c/form-edit.php?id='.$id);}
 $allowed=['text','tel','number','date','textarea','select','radio','checkbox','file','heading'];$rows=[];$used=[];
 foreach($labels as $i=>$label){$label=trim((string)$label);if($label==='')continue;$type=in_array($types[$i]??'text',$allowed,true)?$types[$i]:'text';$key=slug_key((string)($keys[$i]??$label));$base=$key;$n=2;while(isset($used[$key])){$key=$base.'_'.$n++;}$used[$key]=1;$opts=array_values(array_filter(array_map('trim',preg_split('/\r\n|\r|\n|,/',(string)($options[$i]??''))),fn($v)=>$v!==''));$cond=null;$cf=trim((string)($condFields[$i]??''));if($cf!=='')$cond=['field'=>slug_key($cf),'operator'=>(string)($condOps[$i]??'equals'),'value'=>trim((string)($condValues[$i]??''))];$rows[]=['key'=>$key,'label'=>$label,'type'=>$type,'placeholder'=>trim((string)($placeholders[$i]??'')),'help'=>trim((string)($helps[$i]??'')),'options'=>$opts,'condition'=>$cond,'required'=>isset($required[$i])?1:0];}
 try{$db->beginTransaction();if($active)$db->prepare('UPDATE forms SET is_active=0 WHERE location=? AND id<>?')->execute([$location,$id]);$db->prepare('UPDATE forms SET title=?,location=?,description=?,is_active=?,version=version+1 WHERE id=?')->execute([$title,$location,$description,$active,$id]);$db->prepare('DELETE FROM form_fields WHERE form_id=?')->execute([$id]);$ins=$db->prepare('INSERT INTO form_fields(form_id,field_key,label,field_type,placeholder,help_text,options_json,condition_json,is_required,sort_order) VALUES(?,?,?,?,?,?,?,?,?,?)');foreach($rows as $i=>$r)$ins->execute([$id,$r['key'],$r['label'],$r['type'],$r['placeholder']?:null,$r['help']?:null,$r['options']?json_encode($r['options'],JSON_UNESCAPED_UNICODE):null,$r['condition']?json_encode($r['condition'],JSON_UNESCAPED_UNICODE):null,$r['required'],$i]);$db->commit();flash('success','Form saved. The form version was increased so earlier applications keep their original snapshot.');redirect('gadmin8f3k2p9x7m4q6v1c/form-edit.php?id='.$id);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();flash('error','Could not save form: '.$e->getMessage());redirect('gadmin8f3k2p9x7m4q6v1c/form-edit.php?id='.$id);}
