function field_row_html(array $f,int $index):string{$opts=$f['options_json']?implode("\n",json_decode($f['options_json'],true)?:[]):'';$cond=$f['condition_json']?json_decode($f['condition_json'],true):[];ob_start();?><div class="field-row" data-field-row><div class="field-row-head"><strong>Custom field</strong><button type="button" class="btn btn-danger btn-small" data-remove-field>Remove</button></div><div class="form-grid"><div class="field"><label>Label</label><input name="field_label[<?=$index?>]" value="<?=h($f['label'])?>" required></div><div class="field"><label>Type</label><select name="field_type[<?=$index?>]"><?php foreach(['text'=>'Text','tel'=>'Phone','number'=>'Number','date'=>'Date','textarea'=>'Long text','select'=>'Dropdown','radio'=>'Radio buttons','checkbox'=>'Checkboxes','file'=>'File upload','heading'=>'Heading / instructions'] as $k=>$v):?><option value="<?=$k?>" <?=$f['field_type']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="field"><label>Field key</label><input name="field_key[<?=$index?>]" value="<?=h($f['field_key'])?>" placeholder="auto_generated"><small>Used for conditional logic. Lowercase letters/numbers recommended.</small></div><div class="field"><label>Placeholder</label><input name="field_placeholder[<?=$index?>]" value="<?=h($f['placeholder'])?>"></div><div class="field full"><label>Help text</label><input name="field_help[<?=$index?>]" value="<?=h($f['help_text'])?>"></div><div class="field full"><label>Options</label><textarea name="field_options[<?=$index?>]" style="min-height:75px" placeholder="One option per line. Used by dropdown, radio, and checkbox fields."><?=h($opts)?></textarea></div><div class="field"><label>Show only when field key</label><input name="condition_field[<?=$index?>]" value="<?=h($cond['field']??'')?>" placeholder="Leave blank for always visible"></div><div class="field"><label>Condition</label><select name="condition_operator[<?=$index?>]"><?php foreach(['equals'=>'Equals','not_equals'=>'Does not equal','not_empty'=>'Is not empty','empty'=>'Is empty'] as $k=>$v):?><option value="<?=$k?>" <?=($cond['operator']??'equals')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="field"><label>Condition value</label><input name="condition_value[<?=$index?>]" value="<?=h($cond['value']??'')?>"></div><div class="field"><label>Required</label><label><input type="checkbox" name="field_required[<?=$index?>]" value="1" <?=$f['is_required']?'checked':''?>> Applicant must complete this field</label></div></div></div><?php return ob_get_clean();}
