<div class="panel"><div class="panel-head"><div><a href="forms.php">← Forms</a><h2 style="margin:8px 0 0"><?=h($form['title'])?></h2><span class="muted">Current version: v<?=$form['version']?></span></div><?php if($form['is_active']):?><span class="badge" style="background:#1d7a4d">Active</span><?php endif;?></div><form method="post" id="form-builder"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><div class="form-grid"><div class="field"><label>Form title</label><input name="title" value="<?=h($form['title'])?>" required></div><div class="field"><label>Location</label><select name="location"><?php foreach(locations() as $k=>$v):?><option value="<?=h($k)?>" <?=$form['location']===$k?'selected':''?>><?=h($v)?></option><?php endforeach;?></select></div><div class="field full"><label>Description</label><textarea name="description" style="min-height:80px"><?=h($form['description'])?></textarea></div><div class="field full"><label><input type="checkbox" name="is_active" value="1" <?=$form['is_active']?'checked':''?>> Active form for this location</label></div></div><h3 style="margin-top:26px">Required default fields</h3><div class="grid-2"><div class="locked"><strong>Full Name *</strong><br><span class="muted">Always included</span></div><div class="locked"><strong>Email Address *</strong><br><span class="muted">Always included · one application per email</span></div></div><div class="panel-head" style="margin-top:28px"><h3 style="margin:0">Custom fields</h3><button type="button" class="btn btn-secondary" id="add-field">+ Add field</button></div><div id="field-list"><?php foreach($fields as $i=>$f)echo field_row_html($f,$i);?></div><button class="btn btn-primary" style="margin-top:15px">Save Form</button></form></div>
<template id="field-template"><div class="field-row" data-field-row><div class="field-row-head"><strong>Custom field</strong><button type="button" class="btn btn-danger btn-small" data-remove-field>Remove</button></div><div class="form-grid"><div class="field"><label>Label</label><input data-n="field_label" required></div><div class="field"><label>Type</label><select data-n="field_type"><option value="text">Text</option><option value="tel">Phone</option><option value="number">Number</option><option value="date">Date</option><option value="textarea">Long text</option><option value="select">Dropdown</option><option value="radio">Radio buttons</option><option value="checkbox">Checkboxes</option><option value="file">File upload</option><option value="heading">Heading / instructions</option></select></div><div class="field"><label>Field key</label><input data-n="field_key" placeholder="auto_generated"></div><div class="field"><label>Placeholder</label><input data-n="field_placeholder"></div><div class="field full"><label>Help text</label><input data-n="field_help"></div><div class="field full"><label>Options</label><textarea data-n="field_options" style="min-height:75px" placeholder="One option per line"></textarea></div><div class="field"><label>Show only when field key</label><input data-n="condition_field" placeholder="Leave blank for always visible"></div><div class="field"><label>Condition</label><select data-n="condition_operator"><option value="equals">Equals</option><option value="not_equals">Does not equal</option><option value="not_empty">Is not empty</option><option value="empty">Is empty</option></select></div><div class="field"><label>Condition value</label><input data-n="condition_value"></div><div class="field"><label>Required</label><label><input type="checkbox" data-n="field_required" value="1"> Applicant must complete this field</label></div></div></div></template>
<script>document.addEventListener('DOMContentLoaded',()=>{const list=document.getElementById('field-list'),tpl=document.getElementById('field-template');let n=list.querySelectorAll('[data-field-row]').length;const bind=row=>{row.querySelector('[data-remove-field]').onclick=()=>row.remove()};list.querySelectorAll('[data-field-row]').forEach(bind);document.getElementById('add-field').onclick=()=>{const row=tpl.content.firstElementChild.cloneNode(true);row.querySelectorAll('[data-n]').forEach(el=>{el.name=el.dataset.n+'['+n+']'});n++;bind(row);list.appendChild(row);row.scrollIntoView({behavior:'smooth',block:'center'})};});</script>
